CREATE TABLE population_top3000_202608_202609_v1.ref01_date_request_v4 (LIKE population_top3000_202608_202609_v1.ctx02_census_request_v1 INCLUDING ALL);
ALTER TABLE population_top3000_202608_202609_v1.ref01_date_request_v4 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON population_top3000_202608_202609_v1.ref01_date_request_v4 FROM PUBLIC,anon,authenticated;
CREATE TABLE population_top3000_202608_202609_v1.ref01_date_page_v4 (LIKE population_top3000_202608_202609_v1.ctx02_census_page_v1 INCLUDING ALL);
ALTER TABLE population_top3000_202608_202609_v1.ref01_date_page_v4 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON population_top3000_202608_202609_v1.ref01_date_page_v4 FROM PUBLIC,anon,authenticated;
CREATE TABLE population_top3000_202608_202609_v1.ref01_date_admission_v4 (LIKE population_top3000_202608_202609_v1.ctx02_census_admission_v1 INCLUDING ALL);
ALTER TABLE population_top3000_202608_202609_v1.ref01_date_admission_v4 ENABLE ROW LEVEL SECURITY;
