CREATE FUNCTION population_top3000_202608_202609_v1.ref01_date_process_v4(p_attempt uuid,p_token text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;c jsonb;pg population_top3000_202608_202609_v1.ref01_date_page_v4%rowtype;doc population_top3000_202608_202609_v1.source_document%rowtype;z record;v jsonb;anchor jsonb;co text;good boolean;n int:=0;h text;nextid uuid;anchors jsonb;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 c:=population_top3000_202608_202609_v1.ref01_date_context_v4(tid);
 IF NOT(t.payload ? 'source_page_number') THEN RETURN jsonb_build_object('state','BLOCKED','blocker_code','REF01_DATE_STREAM_TERMINAL_REVIEW_V4','resumption_condition',jsonb_build_object('request_key',c->>'request_key','point_date',c->>'as_of','engineering_assignment_event_id',t.input_versions->'engineering_successor_event_id','full_window_complete',false,'family_accepted',false));END IF;
 SELECT * INTO STRICT pg FROM population_top3000_202608_202609_v1.ref01_date_page_v4 WHERE archive_key=c->>'archive_key' AND page_number=(c->>'source_page_number')::int;
 SELECT * INTO STRICT doc FROM population_top3000_202608_202609_v1.source_document WHERE source_id=pg.source_id;
 IF doc.source_sha256 IS DISTINCT FROM pg.source_sha256 OR doc.source_sha256 IS DISTINCT FROM encode(sha256(convert_to(doc.content_text,'UTF8')),'hex') OR doc.content_bytes IS DISTINCT FROM octet_length(doc.content_text) THEN RAISE EXCEPTION 'DATE_SOURCE_HASH';END IF;
 IF t.stage='VALIDATE' THEN RETURN jsonb_build_object('state','BLOCKED','blocker_code','PRACTICAL_DATE_INDEPENDENT_LIFECYCLE_REVIEW_V4','resumption_condition',jsonb_build_object('source_id',pg.source_id,'point_date',c->>'as_of','cohort_sha256',t.input_versions->>'cohort_sha256','full_window_complete',false,'family_accepted',false,'historical_receipt',false));END IF;
 IF t.stage NOT IN('NORMALIZE','DERIVE') THEN RAISE EXCEPTION 'DATE_PROCESS_STAGE';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=t.input_versions->>'cohort_sha256' AND eligible AND point_date='2026-08-03' AND (source_set_sha256 IS DISTINCT FROM '27c81878e9ea5ce6eb05ead025f5c9aaae11108af50ba59ecd65b3402c877c86' OR record_sha256 IS DISTINCT FROM encode(sha256(convert_to(content::text,'UTF8')),'hex'))) THEN RAISE EXCEPTION 'ANCHOR_HASH_CHANGED';END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=t.input_versions->>'cohort_sha256' AND eligible AND point_date='2026-08-03')<>3000 THEN RAISE EXCEPTION 'ANCHOR_POPULATION_CHANGED';END IF;
 IF t.stage='NORMALIZE' THEN
 SELECT jsonb_object_agg(ticker,content) INTO anchors FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 WHERE cohort_sha256=t.input_versions->>'cohort_sha256' AND eligible AND point_date='2026-08-03';
 FOR z IN SELECT value rec,ordinality::int ord FROM jsonb_array_elements(doc.content_text::jsonb->'results') WITH ORDINALITY LOOP
 anchor:=anchors->(z.rec->>'ticker');co:=anchor->>'company_id';
 good:=co IS NOT NULL AND nullif(z.rec->>'composite_figi','') IS NOT NULL AND nullif(z.rec->>'share_class_figi','') IS NOT NULL
 AND z.rec->>'composite_figi'=anchor#>>'{source_record,composite_figi}' AND z.rec->>'share_class_figi'=anchor#>>'{source_record,share_class_figi}'
 AND z.rec->>'cik' IS NOT DISTINCT FROM anchor#>>'{source_record,cik}' AND z.rec->>'type'=anchor#>>'{source_record,type}' AND z.rec->>'primary_exchange'=anchor#>>'{source_record,primary_exchange}' AND z.rec->>'active'='true' AND z.rec->>'market'='stocks' AND z.rec->>'locale'='us';
 v:=jsonb_build_object('source_record',z.rec,'source_sha256',doc.source_sha256,'source_id',doc.source_id,'source_ordinal',z.ord,'point_date',c->>'as_of','cohort_sha256',t.input_versions->>'cohort_sha256','policy_sha256',t.input_versions->>'policy_sha256','membership_acceptance_sha256',t.input_versions->>'membership_acceptance_sha256','company_id',CASE WHEN good THEN co END,'identity_state',CASE WHEN good THEN 'FROZEN_ANCHOR_TICKER_AND_TWO_FIGI_MATCH' ELSE 'UNSELECTED_OR_IDENTITY_LIFECYCLE_REVIEW_REQUIRED' END,'anchor_record_sha256',CASE WHEN anchor IS NOT NULL THEN encode(sha256(convert_to(anchor::text,'UTF8')),'hex') END,'original_historical_receipt',false,'full_window_complete',false,'family_accepted',false);
 INSERT INTO population_top3000_202608_202609_v1.ref01_date_record_v4 VALUES(doc.source_id,z.ord,v,encode(sha256(convert_to(v::text,'UTF8')),'hex'),CASE WHEN good THEN co END,v->>'identity_state',(c->>'as_of')::date) ON CONFLICT DO NOTHING;
 IF FOUND THEN n:=n+1;END IF;
 IF (SELECT content FROM population_top3000_202608_202609_v1.ref01_date_record_v4 WHERE source_id=doc.source_id AND ordinal=z.ord) IS DISTINCT FROM v THEN RAISE EXCEPTION 'DATE_RECORD_CONFLICT';END IF;
 END LOOP;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_date_record_v4 WHERE source_id=doc.source_id)<>pg.result_count THEN RAISE EXCEPTION 'DATE_NORMALIZE_COUNT';END IF;
 UPDATE population_top3000_202608_202609_v1.ref01_date_page_v4 SET normalized_at=clock_timestamp(),normalized_source_records=jsonb_array_length(doc.content_text::jsonb->'results') WHERE archive_key=pg.archive_key AND page_number=pg.page_number;
 ELSE
 IF pg.normalized_source_records IS DISTINCT FROM pg.result_count OR (SELECT count(*) FROM population_top3000_202608_202609_v1.ref01_date_record_v4 WHERE source_id=doc.source_id)<>pg.result_count THEN RAISE EXCEPTION 'DATE_DERIVE_COUNT';END IF;
 FOR z IN SELECT * FROM population_top3000_202608_202609_v1.ref01_date_record_v4 WHERE source_id=doc.source_id AND company_id IS NOT NULL ORDER BY ordinal LOOP
 IF z.record_sha256 IS DISTINCT FROM encode(sha256(convert_to(z.content::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'DATE_RECORD_HASH';END IF;
 v:=z.content-'source_record'||jsonb_build_object('source_record_sha256',z.record_sha256,'ticker',z.content#>>'{source_record,ticker}','evidence_semantics','STRONG_IDENTIFIER_MATCHED_VENDOR_DATE_POINT_NOT_INTERVAL');
 INSERT INTO population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 VALUES(t.input_versions->>'cohort_sha256',doc.source_sha256,z.company_id,z.content#>>'{source_record,ticker}',z.point_date,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
 IF FOUND THEN n:=n+1;END IF;
 IF (SELECT content FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 WHERE cohort_sha256=t.input_versions->>'cohort_sha256' AND source_set_sha256=doc.source_sha256 AND company_id=z.company_id AND ticker=z.content#>>'{source_record,ticker}' AND point_date=z.point_date) IS DISTINCT FROM v THEN RAISE EXCEPTION 'DATED_REPLAY_CONFLICT';END IF;
 END LOOP;
 END IF;
 SELECT encode(sha256(convert_to(coalesce(string_agg(record_sha256,E'\n' ORDER BY ordinal),''),'UTF8')),'hex') INTO h FROM population_top3000_202608_202609_v1.ref01_date_record_v4 WHERE source_id=doc.source_id;
 IF t.stage='DERIVE' THEN SELECT encode(sha256(convert_to(coalesce(string_agg(record_sha256,E'\n' ORDER BY company_id COLLATE "C",ticker COLLATE "C"),''),'UTF8')),'hex') INTO h FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 WHERE cohort_sha256=t.input_versions->>'cohort_sha256' AND source_set_sha256=doc.source_sha256;END IF;
 RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key','REF01_DATE_V4:'||t.stage||':'||doc.source_id,'output_sha256',h,'new_committed_units',n,'immutable_output_ids',jsonb_build_array(doc.source_id),'input_versions',t.input_versions,'family_accepted',false,'full_window_complete',false));
END $f$;
